async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }
  try {
    const rows = await sessionStore.listFor(session.userId, listOptionsFrom(message));
    sendJson(ws, {type: 'session_list', sessions: rows.map(toSummaryFrame)});
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    log.error('ws', 'session list failed', {userId: session.userId, error: reason});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list sessions');
  }
}

function listOptionsFrom({limit, before}: ListSessionsMessage): SessionListOptions {
  const options: SessionListOptions = {};
  if (limit !== undefined) options.limit = limit;
  if (before !== undefined) options.before = before;
  return options;
}

function toSummaryFrame({sessionId, createdAt, updatedAt, entryCount}: SessionSummary): SessionSummaryFrame {
  return {
    sessionId,
    createdAt: createdAt.toISOString(),
    updatedAt: updatedAt.toISOString(),
    entryCount,
  };
}

