async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }
  try {
    const rows = await sessionStore.listFor(session.userId, listOptionsFrom(message));
    sendJson(ws, {type: 'session_list', sessions: rows.map(toSummaryFrame)});
  } catch (error) {
    log.error('ws', 'session list failed', {userId: session.userId, error: (error as Error).message});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list sessions');
  }
}

